import type { CameraCollisionResolver, CameraControllerOptions, CameraInputCommand, CameraMode, CameraTargetState } from './types';

const WORLD_UP = new THREE.Vector3(0, 1, 0);
const EPSILON = 1e-5;
const clampPitch = (pitch: number): number => THREE.MathUtils.clamp(pitch, THREE.MathUtils.degToRad(-78), THREE.MathUtils.degToRad(82));
const smoothingAlpha = (damping: number, deltaSeconds: number): number => 1 - Math.exp(-Math.max(0, damping) * Math.max(0, deltaSeconds));
const toVector3 = (value: Vec3): THREE.Vector3 => new THREE.Vector3(value.x, value.y, value.z);
const toVec3 = (value: THREE.Vector3): Vec3 => ({ x: value.x, y: value.y, z: value.z });

export class CameraController {
  readonly camera: THREE.PerspectiveCamera;
  private mode: CameraMode;
  private target = new THREE.Vector3();
  private targetVelocity = new THREE.Vector3();
  private targetForward = new THREE.Vector3(0, 0, -1);
  private yaw: number;
  private pitch: number;
  private distance: number;
  private readonly defaultYaw: number;
  private readonly defaultPitch: number;
  private readonly defaultDistance: number;
  private readonly minDistance: number;
  private readonly maxDistance: number;
  private readonly positionDamping: number;
  private readonly rotationDamping: number;
  private readonly zoomSpeed: number;
  private readonly orbitSensitivity: number;
  private readonly freeMoveSpeed: number;
  private readonly freeLookSensitivity: number;
  private readonly collisionRadius: number;
  private readonly overviewHeight: number;
  private readonly overviewDistance: number;
  private readonly followHeight: number;
  private readonly followDistance: number;
  private readonly aimHeight: number;
  private collisionResolver?: CameraCollisionResolver;
  private freePosition = new THREE.Vector3();
  private freeYaw = 0;
  private freePitch = 0;
  private freeMove = new THREE.Vector3();
  private desiredPosition = new THREE.Vector3();
  private desiredQuaternion = new THREE.Quaternion();
  private initialized = false;

  constructor(camera: THREE.PerspectiveCamera, options: CameraControllerOptions = {}) {
    this.camera = camera;
    this.mode = options.mode ?? 'aim';
    this.target.copy(toVector3(options.target ?? { x: 0, y: 0, z: 0 }));
    this.yaw = options.yaw ?? 0;
    this.pitch = clampPitch(options.pitch ?? THREE.MathUtils.degToRad(18));
    this.distance = options.distance ?? 6;
    this.defaultYaw = this.yaw;
    this.defaultPitch = this.pitch;
    this.defaultDistance = this.distance;
    this.minDistance = options.minDistance ?? 2.2;
    this.maxDistance = options.maxDistance ?? 16;
    this.positionDamping = options.positionDamping ?? 10;
    this.rotationDamping = options.rotationDamping ?? 12;
    this.zoomSpeed = options.zoomSpeed ?? 0.012;
    this.orbitSensitivity = options.orbitSensitivity ?? 0.004;
    this.freeMoveSpeed = options.freeMoveSpeed ?? 8;
    this.freeLookSensitivity = options.freeLookSensitivity ?? 0.0035;
    this.collisionRadius = options.collisionRadius ?? 0.24;
    this.overviewHeight = options.overviewHeight ?? 12;
    this.overviewDistance = options.overviewDistance ?? 11;
    this.followHeight = options.followHeight ?? 3.2;
    this.followDistance = options.followDistance ?? 6.5;
    this.aimHeight = options.aimHeight ?? 1.65;
    this.distance = THREE.MathUtils.clamp(this.distance, this.minDistance, this.maxDistance);
    this.freePosition.copy(camera.position);
    const euler = new THREE.Euler().setFromQuaternion(camera.quaternion, 'YXZ');
    this.freePitch = clampPitch(euler.x);
    this.freeYaw = euler.y;
  }

  getMode(): CameraMode { return this.mode; }
  getDistance(): number { return this.distance; }
  getTarget(): Vec3 { return toVec3(this.target); }
  setCollisionResolver(resolver?: CameraCollisionResolver): void { this.collisionResolver = resolver; }

  setTarget(state: Vec3 | CameraTargetState): void {
    const isState = 'position' in state;
    const position = isState ? state.position : state;
    this.target.copy(toVector3(position));
    if (isState && state.velocity) this.targetVelocity.copy(toVector3(state.velocity));
    else this.targetVelocity.set(0, 0, 0);
    if (isState && state.forward) {
      this.targetForward.copy(toVector3(state.forward));
      this.targetForward.y = 0;
      if (this.targetForward.lengthSq() > EPSILON) this.targetForward.normalize();
    }
  }

  setMode(mode: CameraMode): void {
    if (mode === this.mode) return;
    if (mode === 'free') this.captureFreePose();
    this.mode = mode;
  }

  reset(): void {
    this.yaw = this.defaultYaw;
    this.pitch = this.defaultPitch;
    this.distance = THREE.MathUtils.clamp(this.defaultDistance, this.minDistance, this.maxDistance);
    if (this.mode === 'free') {
      this.mode = 'aim';
      this.initialized = false;
    }
  }

  handleCommand(command: CameraInputCommand): void {
    switch (command.type) {
      case 'orbit':
        this.yaw -= command.yawDelta * this.orbitSensitivity;
        this.pitch = clampPitch(this.pitch - command.pitchDelta * this.orbitSensitivity);
        break;
      case 'zoom':
        this.distance = THREE.MathUtils.clamp(this.distance + command.delta * this.zoomSpeed, this.minDistance, this.maxDistance);
        break;
      case 'reset': this.reset(); break;
      case 'set-mode': this.setMode(command.mode); break;
      case 'free-move': this.freeMove.set(command.right, command.up ?? 0, command.forward); break;
      case 'free-look':
        this.freeYaw -= command.yawDelta * this.freeLookSensitivity;
        this.freePitch = clampPitch(this.freePitch - command.pitchDelta * this.freeLookSensitivity);
        break;
    }
  }

  update(deltaSeconds: number): void {
    const dt = Math.max(0, Math.min(deltaSeconds, 0.1));
    if (this.mode === 'free') this.updateFree(dt);
    else this.updateTracked(dt);
  }

  private updateTracked(deltaSeconds: number): void {
    const focus = this.target.clone();
    if (this.mode === 'follow') focus.addScaledVector(this.targetVelocity, 0.08);
    const orbit = new THREE.Vector3(Math.sin(this.yaw) * Math.cos(this.pitch), Math.sin(this.pitch), Math.cos(this.yaw) * Math.cos(this.pitch));

    if (this.mode === 'overview') {
      this.desiredPosition.copy(focus).add(new THREE.Vector3(Math.sin(this.yaw) * this.overviewDistance, this.overviewHeight, Math.cos(this.yaw) * this.overviewDistance));
    } else if (this.mode === 'follow') {
      const backward = this.targetForward.lengthSq() > EPSILON ? this.targetForward.clone().multiplyScalar(-this.followDistance) : orbit.clone().multiplyScalar(this.followDistance);
      backward.y = 0;
      this.desiredPosition.copy(focus).add(backward).add(new THREE.Vector3(0, this.followHeight, 0));
    } else {
      this.desiredPosition.copy(focus).addScaledVector(orbit, this.distance);
      this.desiredPosition.y += this.aimHeight;
    }

    this.applyCollision(focus, this.desiredPosition);
    this.computeLookQuaternion(this.desiredPosition, focus, this.desiredQuaternion);
    this.applySmoothedPose(deltaSeconds);
  }

  private updateFree(deltaSeconds: number): void {
    const orientation = new THREE.Quaternion().setFromEuler(new THREE.Euler(this.freePitch, this.freeYaw, 0, 'YXZ'));
    const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(orientation);
    const right = new THREE.Vector3(1, 0, 0).applyQuaternion(orientation);
    forward.y = 0; right.y = 0;
    if (forward.lengthSq() > EPSILON) forward.normalize();
    if (right.lengthSq() > EPSILON) right.normalize();
    this.freePosition.addScaledVector(forward, this.freeMove.z * this.freeMoveSpeed * deltaSeconds);
    this.freePosition.addScaledVector(right, this.freeMove.x * this.freeMoveSpeed * deltaSeconds);
    this.freePosition.y += this.freeMove.y * this.freeMoveSpeed * deltaSeconds;
    this.desiredPosition.copy(this.freePosition);
    this.desiredQuaternion.copy(orientation);
    this.applySmoothedPose(deltaSeconds);
  }

  private applyCollision(focus: THREE.Vector3, desired: THREE.Vector3): void {
    if (!this.collisionResolver) return;
    desired.copy(toVector3(this.collisionResolver.resolveCameraPosition(toVec3(focus), toVec3(desired), this.collisionRadius)));
  }

  private computeLookQuaternion(position: THREE.Vector3, focus: THREE.Vector3, out: THREE.Quaternion): void {
    const direction = focus.clone().sub(position);
    if (direction.lengthSq() <= EPSILON) { out.copy(this.camera.quaternion); return; }
    out.setFromRotationMatrix(new THREE.Matrix4().lookAt(position, focus, WORLD_UP));
  }

  private applySmoothedPose(deltaSeconds: number): void {
    if (!this.initialized) {
      this.camera.position.copy(this.desiredPosition);
      this.camera.quaternion.copy(this.desiredQuaternion);
      this.initialized = true;
      return;
    }
    this.camera.position.lerp(this.desiredPosition, smoothingAlpha(this.positionDamping, deltaSeconds));
    this.camera.quaternion.slerp(this.desiredQuaternion, smoothingAlpha(this.rotationDamping, deltaSeconds));
  }

  private captureFreePose(): void {
    this.freePosition.copy(this.camera.position);
    const euler = new THREE.Euler().setFromQuaternion(this.camera.quaternion, 'YXZ');
    this.freePitch = clampPitch(euler.x);
    this.freeYaw = euler.y;
  }
}
