import { describe, expect, it } from 'vitest';
import * as THREE from 'three';
import { CameraController } from './CameraController';
import type { CameraCollisionResolver } from './types';

const makeCamera = () => new THREE.PerspectiveCamera(60, 16 / 9, 0.1, 100);

describe('CameraController', () => {
  it('supports tracked camera modes and reset', () => {
    const camera = makeCamera();
    const controller = new CameraController(camera, { distance: 7, minDistance: 2, maxDistance: 10 });
    controller.setTarget({ x: 1, y: 0, z: 2 });
    controller.update(1 / 60);
    expect(controller.getMode()).toBe('aim');
    expect(camera.position.length()).toBeGreaterThan(0);
    controller.handleCommand({ type: 'set-mode', mode: 'overview' });
    controller.update(1 / 60);
    expect(controller.getMode()).toBe('overview');
    controller.handleCommand({ type: 'zoom', delta: 10000 });
    expect(controller.getDistance()).toBe(10);
    controller.handleCommand({ type: 'reset' });
    expect(controller.getDistance()).toBe(7);
  });

  it('moves in free-camera mode from abstract input commands', () => {
    const camera = makeCamera();
    camera.position.set(0, 2, 5);
    const controller = new CameraController(camera, { freeMoveSpeed: 10 });
    controller.setMode('free');
    controller.handleCommand({ type: 'free-move', forward: 1, right: 0 });
    controller.update(0.1);
    const before = camera.position.clone();
    controller.update(0.1);
    expect(camera.position.distanceTo(before)).toBeGreaterThan(0);
  });

  it('uses the collision resolver to prevent camera clipping', () => {
    const camera = makeCamera();
    const resolver: CameraCollisionResolver = { resolveCameraPosition: (_from, desired) => ({ ...desired, y: 3 }) };
    const controller = new CameraController(camera, { positionDamping: 1000 });
    controller.setCollisionResolver(resolver);
    controller.setTarget({ x: 0, y: 0, z: 0 });
    controller.update(1 / 60);
    expect(camera.position.y).toBeCloseTo(3);
  });
});
